/*
 * A segunda linha da aba "Mensagens" do perfil (`.user-navigation-secondary`
 * de `templates/user/messages.gjs`): o seletor de caixa ("Caixa de entrada ▾",
 * com a bolinha de não lidas), as abas da caixa (Últimos, Enviadas, Novo,
 * Não lidos, Arquivo) e, à direita, "✉ Nova mensagem".
 *
 * O Discourse lista no seletor a caixa pessoal e as dos grupos de que a pessoa
 * participa. O flarum/messages não tem caixa de grupo (toda conversa é entre
 * duas pessoas), então o seletor tem só a pessoal — como o Discourse de quem
 * não está em nenhum grupo com mensagens.
 */
import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Dropdown from 'flarum/common/components/Dropdown';
import Icon from 'flarum/common/components/Icon';
import LinkButton from 'flarum/common/components/LinkButton';
import classList from 'flarum/common/utils/classList';
import { t } from '../../utils/settings';
import { availableBoxes, boxCounts, boxHref, canSendMessages, groupLabel, messageGroupModel, openMessageComposer, totalUnread } from './util';
/** Os ícones do Discourse (`envelope`, `reply`, `circle-exclamation`, `circle-plus`, `box-archive`). */
const ICONS = {
  inbox: 'far fa-envelope',
  sent: 'fas fa-reply',
  new: 'fas fa-circle-exclamation',
  unread: 'fas fa-circle-plus',
  archive: 'fas fa-box-archive',
  group: 'far fa-envelope'
};
export default class MessagesNav extends Component {
  view() {
    const {
      user,
      box
    } = this.attrs;
    const viewingSelf = app.session.user === user;
    return m("nav", {
      className: "CanelaMessagesNav",
      "aria-label": t('messages.nav.label')
    }, m("div", {
      className: "CanelaMessagesNav-inbox"
    }, this.inboxDropdown(user)), m("div", {
      className: "CanelaUserNav CanelaMessagesNav-pillsWrap"
    }, m("ul", {
      className: "CanelaMessagesNav-pills"
    }, (box === 'group' ? ['group'] : availableBoxes().filter(item => item !== 'group')
    // Novo e Não lidos só no próprio perfil (`viewingSelf`).
    ).filter(item => viewingSelf || item !== 'new' && item !== 'unread').map(item => m("li", {
      className: classList({
        active: item === box
      })
    }, m(LinkButton, {
      href: boxHref(user, item),
      icon: ICONS[item],
      active: item === box,
      className: `CanelaMessagesNav-pill CanelaMessagesNav-pill--${item}`
    }, this.label(item)))))), m("div", {
      className: "CanelaMessagesNav-controls"
    }, viewingSelf && canSendMessages() ? m(Button, {
      className: "Button Button--primary CanelaMessagesNav-new",
      icon: "fas fa-envelope",
      onclick: () => openMessageComposer({
        onsubmit: () => this.attrs.onsent?.()
      }).catch(() => {})
    }, t('messages.nav.new_message')) : null));
  }
  label(box) {
    const counts = boxCounts();
    if (box === 'new' && counts.new) return t('messages.nav.new_with_count', {
      count: counts.new
    });
    if (box === 'unread' && counts.unread) return t('messages.nav.unread_with_count', {
      count: counts.unread
    });
    // Na caixa do grupo a aba é a "Últimos" dela.
    if (box === 'group') return t('messages.nav.inbox');
    return t(`messages.nav.${box}`);
  }

  /**
   * "Caixa de entrada ▾" (`messages-dropdown`, um botão padrão): a bolinha
   * aparece quando há novas ou não lidas, como o `d-icon-d-unread` de quem
   * não pediu as contagens na barra lateral.
   */
  inboxDropdown(user) {
    const onGroup = this.attrs.box === 'group';
    const unread = totalUnread() > 0;
    const groupCount = boxCounts().group;
    const group = availableBoxes().includes('group') ? messageGroupModel() : null;
    const label = t('messages.nav.inbox_box');
    const current = onGroup && group ? groupLabel(group) : label;
    return m(Dropdown, {
      className: "CanelaMessagesNav-dropdown",
      buttonClassName: "Button CanelaMessagesNav-trigger",
      menuClassName: "CanelaMessagesNav-menu",
      caretIcon: "fas fa-angle-down",
      label: [onGroup ? m(Icon, {
        name: "fas fa-inbox",
        className: "CanelaMessagesNav-triggerIcon"
      }) : null, m("span", {
        className: "CanelaMessagesNav-triggerLabel"
      }, current), (onGroup ? groupCount : unread) ? m(Icon, {
        name: "fas fa-circle",
        className: "CanelaMessagesNav-unreadDot"
      }) : null],
      accessibleToggleLabel: t('messages.nav.all'),
      title: t('messages.nav.all')
    }, m(Button, {
      className: classList('Button CanelaMessagesNav-option', {
        'is-selected': !onGroup
      }),
      active: !onGroup,
      onclick: () => m.route.set(boxHref(user))
    }, label, unread ? m(Icon, {
      name: "fas fa-circle",
      className: "CanelaMessagesNav-unreadDot"
    }) : null), group ? m(Button, {
      className: classList('Button CanelaMessagesNav-option', {
        'is-selected': onGroup
      }),
      icon: "fas fa-inbox",
      active: onGroup,
      onclick: () => m.route.set(boxHref(user, 'group'))
    }, groupLabel(group), groupCount ? m(Icon, {
      name: "fas fa-circle",
      className: "CanelaMessagesNav-unreadDot"
    }) : null) : null);
  }
}
flarum.reg.add('ramon-canela', 'forum/features/messages/MessagesNav', MessagesNav);