/*
 * A aba "Mensagens" do perfil (`/u/:username/messages[/:box]`), como a
 * `user-messages-page` do Discourse: a linha das caixas e a lista de
 * mensagens no formato da lista de tópicos.
 *
 * Mensagens são pessoais: a API do flarum/messages só devolve as conversas de
 * quem pede, então a aba só existe no próprio perfil; no de outra pessoa a
 * página volta para o perfil.
 */
import app from 'flarum/forum/app';
import UserPage from 'flarum/forum/components/UserPage';
import Icon from 'flarum/common/components/Icon';
import Link from 'flarum/common/components/Link';
import BoxListState, { refreshCounts } from './BoxListState';
import MessagesList from './MessagesList';
import MessagesNav from './MessagesNav';
import { t } from '../../utils/settings';
import { availableBoxes, canSendMessages, messagesOn, messageStaff } from './util';
export default class UserMessagesPage extends UserPage {
  boxState = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.loadUser(m.route.param('username'));
  }
  show(user) {
    super.show(user);
    if (!messagesOn() || app.session.user !== user) {
      m.route.set(app.route.user(user), {}, {
        replace: true
      });
      return;
    }
    app.setTitle(t('messages.page.title'));
  }

  /** A caixa do endereço (a rota das caixas ou, sem o backend, a query). */
  box() {
    const box = m.route.param('box');
    return box && availableBoxes().includes(box) ? box : 'inbox';
  }

  /** O estado da caixa atual; trocar de aba (mesma página, outra rota) troca o estado. */
  listState() {
    const box = this.box();
    if (!this.boxState || this.boxState.getParams().box !== box) {
      this.boxState = BoxListState.forBox(box);
      this.boxState.refresh().catch(() => {});
    }
    return this.boxState;
  }
  content() {
    if (!this.user || app.session.user !== this.user || !messagesOn()) return null;
    const state = this.listState();
    return m("div", {
      className: "CanelaUserMessages"
    }, m(MessagesNav, {
      user: this.user,
      box: this.box(),
      onsent: () => {
        state.refresh().catch(() => {});
        refreshCounts();
      }
    }), m("section", {
      className: "CanelaUserMessages-content"
    }, m(MessagesList, {
      state: state,
      empty: () => this.emptyState()
    })));
  }

  /**
   * O estado vazio do Discourse (`user.no_messages_title` / `_body`). O texto
   * aponta para o botão de mensagem do cartão de usuário e para a página
   * "Sobre", onde estão os membros da equipe.
   */
  emptyState() {
    const aboutHref = app.routes.about ? app.route('about') : app.route('index');
    return m("div", {
      className: "CanelaMessagesEmpty empty-state"
    }, m("div", {
      className: "empty-state__container --text-only"
    }, m("span", {
      className: "empty-state__title",
      role: "heading",
      "aria-level": 2
    }, t('messages.empty.title')), canSendMessages() ? m("div", {
      className: "empty-state__body"
    }, m("p", null, app.translator.trans('ramon-canela.forum.messages.empty.body_1', {
      icon: m(Icon, {
        name: "fas fa-envelope"
      })
    })), m("p", null, app.translator.trans('ramon-canela.forum.messages.empty.body_2', {
      a: m(Link, {
        href: aboutHref,
        onclick: event => messageStaff(event)
      })
    }))) : null));
  }
}
flarum.reg.add('ramon-canela', 'forum/features/messages/UserMessagesPage', UserMessagesPage);